}
/* travelling signals: chip -> beam -> prism -> ray -> label */
function spawn(t){
 if(still||t-spawnAt<(mob?900:640))return;spawnAt=t;
 if(mob){parts.push({ph:1,t:0,d:1100,from:{x:-6,y:G.y0}});return}
 for(var i=0;i<lanes.length;i++){var L=lanes[(ks+i)%lanes.length];if(L.al>.6&&L.a){ks+=i+1;parts.push({ph:0,t:0,d:1500+Math.random()*400,L:L,a:{x:L.a.x,y:L.a.y},cp:{x:L.cp.x,y:L.cp.y}});return}}
