 background:radial-gradient(70% 52% at 50% -4%,var(--s2),transparent 72%),radial-gradient(55% 45% at 50% 74%,oklch(16.5% .04 272),transparent 74%),linear-gradient(180deg,var(--s1),var(--s0) 72%)}
.stage :focus-visible{outline-color:oklch(80% .12 256)}
.st-c{position:relative;z-index:3;width:100%;max-width:1080px;margin:0 auto;padding:clamp(104px,14.5vh,150px) 24px 0}
.st-c h1{color:var(--s-ink);max-width:13em;margin:0 auto;font-size:clamp(38px,5.3vw,68px);text-wrap:balance}
.sub{margin:18px auto 0;font-size:clamp(17px,1.75vw,20px);line-height:1.5;max-width:31em;color:var(--s-mut);text-wrap:balance}
.st-room{flex:1 0 clamp(300px,40vh,440px)}
/* the input with its two routes */
.cap{display:flex;align-items:center;gap:6px;margin:30px auto 0;max-width:700px;padding:6px 6px 6px 20px;border-radius:18px;text-align:left;background:oklch(98.6% .004 275);
 box-shadow:0 0 0 1px oklch(100% 0 0/.1),0 18px 50px -16px oklch(4% .03 278/.9),0 0 90px -24px oklch(72% .12 268/.45);transition:box-shadow .3s var(--ease)}
.cap:focus-within{box-shadow:0 0 0 3px oklch(70% .15 256/.6),0 18px 50px -16px oklch(4% .03 278/.9),0 0 90px -24px oklch(72% .12 268/.5)}
