.routes{display:flex;gap:6px;flex:none}
.rt{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 18px 0 15px;border-radius:13px;font-weight:600;font-size:15px;letter-spacing:-.005em;color:oklch(99.4% .003 270);text-decoration:none;white-space:nowrap;cursor:pointer;transition:background .2s,box-shadow .35s var(--ease)}
.rt:hover{text-decoration:none}
.rt svg{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.rt-test{background:var(--test)}.rt-test:hover,.rt-test.on{background:var(--test-d);box-shadow:0 6px 18px -6px oklch(55% .19 256/.7)}
.rt-audit{background:var(--audit)}.rt-audit:hover,.rt-audit.on{background:var(--audit-d);box-shadow:0 6px 18px -6px oklch(52% .2 295/.7)}
.rt:focus-visible{outline:2px solid var(--test);outline-offset:3px;border-radius:13px}
