/* two routes from one input. Enter runs Doc-test. Doc-audit opens with the repo filled in. */
function repoOf(s){
 s=clean(s);var m=/^(?:https?:\/\/)?(?:www\.)?github\.com\/([A-Za-z0-9-]+)\/([\w.-]+?)(?:\.git)?(\/.*)?$/i.exec(s);
 if(m)return{repo:m[1]+"/"+m[2],deep:!!(m[3]&&!/^\/(tree\/[^\/]+\/?)?$/.test(m[3]))};
 m=/^([A-Za-z0-9-]+)\/([\w.-]+?)(?:\.git)?$/.exec(s);
 return m?{repo:m[1]+"/"+m[2],deep:false}:null;
}
function say(parts,cls){
 /* parts: strings and [label, fn, audit?] buttons. Built with DOM calls, never HTML */
 var el=$("hint");el.textContent="";el.className="hint "+(cls||"warn");
 parts.forEach(function(p){
  if(typeof p==="string"){el.appendChild(document.createTextNode(p));return}
  var b=document.createElement("button");b.type="button";b.className="hb"+(p[2]?" au":"");b.textContent=p[0];b.addEventListener("click",p[1]);el.appendChild(b);
 });
}
function toAudit(r){location.href="doc-audit/"+(r?"?repo="+encodeURIComponent(r):"")}
function route(kind){
 var s=clean($("u").value),r=s?repoOf(s):null;
 if(kind==="audit"){
  if(!s)return toAudit("");
  if(r)return toAudit(r.repo);
  if(norm(s).q)return say(["Doc-audit reads a GitHub repo, like dbt-labs/dbt-core. ",["Test the docs for “"+s.slice(0,40)+"” instead",function(){show()}]]);
  return say(["Doc-audit reads a GitHub repo, not a docs page. ",["Test this page instead",function(){show()}]]);
 }
 if(!s){$("u").focus();return}
 if(r&&!r.deep)return say(["That looks like a GitHub repo. ",["Audit "+r.repo,function(){toAudit(r.repo)},1]," or ",["test its README",function(){show()}],"."]);
 show();
}
