var QS=new URLSearchParams(location.search),id=QS.get("id");
if(id&&/^[a-z0-9-]+$/i.test(id)){fetch("../audits/"+id+".json").then(function(r){if(!r.ok)throw 0;return r.json()}).then(render).catch(function(){listAudits()})}
else{
