.sn-h{font-size:12px;font-weight:600;color:var(--sn-mut);padding:8px 10px 4px}
.sn-it{display:grid;grid-template-columns:22px 1fr auto;gap:2px 10px;align-items:center;padding:8px 10px;border-radius:11px}
.sn-it:hover,.sn-it:focus-visible{background:var(--sn-hover);outline:0}
.sn-it svg{width:16px;height:16px;fill:none;stroke:var(--sn-mut);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;grid-row:1/span 2}
.sn-it b{font-size:14px;font-weight:600}.sn-it small{grid-column:2;font-size:12.5px;color:var(--sn-mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sn-it i{font-style:normal;font-size:12px;font-weight:600;color:var(--sn-mut);grid-row:1/span 2;grid-column:3}
.sn-it i.ok{color:var(--sn-ok)}
.sn-big{display:grid;grid-template-columns:40px 1fr;gap:1px 12px;align-items:center;padding:10px;border-radius:14px}
.sn-big .sn-tile{width:40px;height:40px;border-radius:11px;grid-row:1/span 2}.sn-big .sn-tile svg{width:21px;height:21px}
.sn-big b{font-size:16px;letter-spacing:-.015em}.sn-big small{font-size:13px;color:var(--sn-mut)}
.sn-big.b-test{background:var(--sn-test-bg)}.sn-big.b-audit{background:var(--sn-audit-bg);margin-top:6px}
.sn-big[aria-current=page]{box-shadow:inset 0 0 0 1.5px var(--sn-test)}.sn-big.b-audit[aria-current=page]{box-shadow:inset 0 0 0 1.5px var(--sn-audit)}
.sn-nav :focus-visible{outline:3px solid var(--sn-test);outline-offset:2px}
/* below 1080 px the section links move into the menu */
@media(max-width:1079px){
 .sn-links,.sn-sep,.sn-gh{display:none}
 .sn-burger{display:inline-grid}
 .sn-mm.mm-more{left:auto;right:0;transform:translateY(-6px);width:min(380px,calc(100vw - 24px));display:block;max-height:calc(100vh - 90px);overflow:auto}
 .sn-mm.mm-more.on{transform:none}
}
@media(min-width:1080px){.sn-mm.mm-more{display:none}}
/* below 760 px the two tools move into the menu too, so the bar is brand, Try it, menu */
@media(max-width:759px){
 #sitenav{height:72px}
 .sn-nav{left:12px;right:12px;transform:none;width:auto;max-width:none}
 .sn-bar{height:52px;padding:0 6px 0 12px}
 .sn-apps{display:none}
 .sn-try{height:38px;padding:0 15px}
 .sn-mm{left:0;width:100%;transform:translateY(-6px);grid-template-columns:1fr;max-height:calc(100vh - 90px);overflow:auto}
 .sn-mm.on{transform:none}
 .sn-mm.mm-more{width:100%}
}
@media(prefers-reduced-motion:reduce){.sn-mm,.sn-car,.sn-bar,.sn-burger svg{transition:none!important}}

