// usage: node shot.js <outdir> <scenario...>
const { chromium } = require("D:/Atharva/video-studio/node_modules/playwright");
const OUT = process.argv[2];
const which = process.argv.slice(3);
const BASE = "http://127.0.0.1:8765/";
(async () => {
  const browser = await chromium.launch({ executablePath: "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe", args: ["--hide-scrollbars"] });
  const errs = [];
  async function page(w, h, opts = {}) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: opts.dpr || 1, reducedMotion: opts.rm ? "reduce" : "no-preference", hasTouch: !!opts.touch, isMobile: !!opts.mobile, javaScriptEnabled: opts.nojs ? false : true });
    const p = await ctx.newPage();
    p.on("console", m => { if (m.type() === "error") errs.push(`[${w}] ${m.text()}`); });
    p.on("pageerror", e => errs.push(`[${w}] pageerror ${e.message}`));
    return p;
  }
  const S = {
    async hero(w, h, name, opts) {
      const p = await page(w, h, opts);
      await p.goto(BASE + (opts && opts.path || ""), { waitUntil: "networkidle" });
      await p.waitForTimeout(opts && opts.wait || 3200);
      if (opts && opts.act) await opts.act(p);
      await p.screenshot({ path: `${OUT}/${name}.png`, fullPage: !!(opts && opts.full) });
      if (opts && opts.measure) console.log(name, JSON.stringify(await p.evaluate(opts.measure)));
      await p.context().close();
    },
  };
  const sideScroll = () => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth });
  const jobs = {
    h1440: () => S.hero(1440, 900, "hero-1440", { measure: sideScroll }),
    h1280: () => S.hero(1280, 800, "hero-1280", { measure: sideScroll }),
    h1024: () => S.hero(1024, 768, "hero-1024", { measure: sideScroll }),
    h768: () => S.hero(768, 1024, "hero-768", { measure: sideScroll }),
    h375: () => S.hero(375, 812, "hero-375", { measure: sideScroll, mobile: true, touch: true, dpr: 2 }),
    h375full: () => S.hero(375, 812, "hero-375-full", { full: true, mobile: true, touch: true, dpr: 1 }),
    h1920: () => S.hero(1920, 1080, "hero-1920", { measure: sideScroll }),
    hoverTest: () => S.hero(1440, 900, "hover-test", { act: async p => { await p.hover("#goT"); await p.waitForTimeout(900); } }),
    hoverAudit: () => S.hero(1440, 900, "hover-audit", { act: async p => { await p.hover("#goA"); await p.waitForTimeout(1200); } }),
    focus: () => S.hero(1440, 900, "focus-audit", { act: async p => { await p.focus("#u"); await p.keyboard.press("Tab"); await p.keyboard.press("Tab"); await p.waitForTimeout(1200); } }),
    rm: () => S.hero(1440, 900, "reduced-motion", { rm: true, wait: 800 }),
    nojs: () => S.hero(1440, 900, "no-js", { nojs: true, wait: 300 }),
    nojs375: () => S.hero(375, 812, "no-js-375", { nojs: true, wait: 300, full: true }),
    full1440: () => S.hero(1440, 900, "full-1440", { full: true, wait: 1500 }),
    mis: () => S.hero(1440, 900, "mismatch-test", { act: async p => { await p.fill("#u", "github.com/dbt-labs/dbt-core"); await p.keyboard.press("Enter"); await p.waitForTimeout(400); } }),
    mis2: () => S.hero(1440, 900, "mismatch-audit", { act: async p => { await p.fill("#u", "https://docs.getdbt.com/guides/duckdb"); await p.click("#goA"); await p.waitForTimeout(500); } }),
    nav_test: () => S.hero(1280, 800, "nav-doc-test-1280", { path: "doc-test/", wait: 1500 }),
    nav_audit: () => S.hero(1280, 800, "nav-doc-audit-1280", { path: "doc-audit/", wait: 1500 }),
    nav_plan: () => S.hero(1280, 800, "nav-plan-1280", { path: "plan/", wait: 1500 }),
    nav_test375: () => S.hero(375, 812, "nav-doc-test-375", { path: "doc-test/", wait: 1500, mobile: true, touch: true }),
    nav_audit375: () => S.hero(375, 812, "nav-doc-audit-375", { path: "doc-audit/", wait: 1500, mobile: true, touch: true }),
    nav_plan375: () => S.hero(375, 812, "nav-plan-375", { path: "plan/", wait: 1500, mobile: true, touch: true }),
    nav_menu375: () => S.hero(375, 812, "nav-menu-375", { wait: 1500, mobile: true, touch: true, act: async p => { await p.click("#sn-b-more"); await p.waitForTimeout(500); } }),
    nav_scrolled: () => S.hero(1440, 900, "nav-scrolled-1440", { wait: 1500, act: async p => { await p.evaluate(() => document.getElementById("steps").scrollIntoView()); await p.waitForTimeout(1200); } }),
    nav_mega: () => S.hero(1440, 900, "nav-mega-audit", { wait: 1500, act: async p => { await p.hover("#sn-b-audit"); await p.waitForTimeout(1200); } }),
    audit_prefill: () => S.hero(1280, 800, "audit-prefill", { path: "doc-audit/?repo=dbt-labs%2Fdbt-core", wait: 1500 }),
    audit_prefill2: () => S.hero(1280, 800, "audit-prefill-new", { path: "doc-audit/?repo=%3Cimg%20src%3Dx%3E/fastapi", wait: 1500 }),
    tap375: () => S.hero(375, 812, "tap-audit-375", { mobile: true, touch: true, dpr: 2, act: async p => { await p.tap("#goA"); await p.waitForTimeout(1000); } }),
    perf: async () => {
      const p = await page(1440, 900);
      await p.goto(BASE, { waitUntil: "networkidle" });
      await p.waitForTimeout(3000);
      const r = await p.evaluate(() => new Promise(res => {
        const ts = []; let last = performance.now(); const t0 = last;
        function f(t) { ts.push(t - last); last = t; if (t - t0 < 5000) requestAnimationFrame(f); else res(ts); }
        requestAnimationFrame(f);
      }));
      r.sort((a, b) => a - b);
      const n = r.length, avg = r.reduce((a, b) => a + b, 0) / n;
      console.log("frames", n, "avg", avg.toFixed(2), "p50", r[Math.floor(n * .5)].toFixed(2), "p95", r[Math.floor(n * .95)].toFixed(2), "max", r[n - 1].toFixed(2), "over20ms", r.filter(x => x > 20).length);
      // CLS
      const cls = await p.evaluate(() => new Promise(res => { let v = 0; new PerformanceObserver(l => { for (const e of l.getEntries()) if (!e.hadRecentInput) v += e.value; }).observe({ type: "layout-shift", buffered: true }); setTimeout(() => res(v), 300); }));
      console.log("CLS", cls);
      // scripting cost per frame of the scene
      const cost = await p.evaluate(() => new Promise(res => {
        const orig = window.requestAnimationFrame; let tot = 0, n = 0;
        window.requestAnimationFrame = function (cb) { return orig.call(window, function (t) { const a = performance.now(); cb(t); tot += performance.now() - a; n++; }); };
        setTimeout(() => res({ n, avg: tot / Math.max(1, n) }), 3000);
      }));
      console.log("rAF callback cost ms", JSON.stringify(cost));
      await p.context().close();
    },
  };
  for (const k of which) { try { await jobs[k](); } catch (e) { console.log("ERR", k, e.message); } }
  console.log("console errors:", errs.length ? errs.join("\n") : "none");
  await browser.close();
})();

